50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        String normalizedAddress = normalizeAddress(owner.getAddress());
108	        if (normalizedAddress.isEmpty()) {
109	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
110	                "Address must not be blank after normalization");
111	        }
112	        owner.setAddress(normalizedAddress);
113	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        owner.setEmail(normalizeEmail(owner.getEmail()));
116	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
117	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
118	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
119	        owner.setRegistrationDate(businessDate);
120	        long createdToday = this.clinicService.findAllOwners().stream()
121	            .map(Owner::getRegistrationDate)
122	            .filter(businessDate::equals)
123	            .count();
124	        if (createdToday >= 100) {
125	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
126	                "The maximum number of owners for today has already been reached");
127	        }
128	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
129	            .map(Owner::getTelephone)
130	            .filter(java.util.Objects::nonNull)
131	            .anyMatch(normalizedTelephone::equals);
132	        if (telephoneInUse) {
133	            throw new ResponseStatusException(HttpStatus.CONFLICT,
134	                "An owner with this telephone number already exists");
135	        }
136	        String lastNameKey = normalizeForHousehold(owner.getLastName());
137	        String addressKey = normalizeForHousehold(owner.getAddress());
138	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
139	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
140	                && normalizeForHousehold(existing.getAddress()).equals(addressKey))
141	            .toList();
142	        if (!householdMembers.isEmpty()) {
143	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
144	                throw new ResponseStatusException(HttpStatus.CONFLICT,
145	                    "An owner with this last name already exists at this address");
146	            }
147	            String householdId = householdId(lastNameKey, addressKey);
148	            owner.setHouseholdId(householdId);
149	            for (Owner member : householdMembers) {
150	                if (!householdId.equals(member.getHouseholdId())) {
151	                    member.setHouseholdId(householdId);
152	                    this.clinicService.saveOwner(member);
153	                }
154	            }
155	        }
156	        String cityKey = normalizeForHousehold(owner.getCity());
157	        long cityCount = this.clinicService.findAllOwners().stream()
158	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
159	            .count();
160	        if (cityCount >= 50) {
161	            throw new ResponseStatusException(HttpStatus.CONFLICT,
162	                "This city already has the maximum number of owners");
163	        }
164	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
165	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
166	        this.clinicService.saveOwner(owner);
167	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
168	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
169	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
170	        headers.setLocation(UriComponentsBuilder.newInstance()
171	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
172	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
173	    }
174	
175	    /**
176	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
177	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
178	     * to the effective registration date (whether supplied in the request or defaulted to the server
179	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
180	     * business day.
181	     *
182	     * @param date the effective registration date
183	     * @return the same date if it is a weekday, otherwise the following Monday
184	     */
185	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
186	        return switch (date.getDayOfWeek()) {
187	            case SATURDAY -> date.plusDays(2);
188	            case SUNDAY -> date.plusDays(1);
189	            default -> date;
190	        };
191	    }
192	
193	    /**
194	     * Counts the owners that already exist (before the current create) whose first and last names
195	     * both match the supplied names, compared case-insensitively. The returned value is captured on
196	     * the new owner at creation time and does not change as further owners are added later.
197	     *
198	     * @param firstName the new owner's first name
199	     * @param lastName  the new owner's last name
200	     * @return the number of pre-existing namesake owners
201	     */
202	    private int namesakeCount(String firstName, String lastName) {
203	        return (int) this.clinicService.findAllOwners().stream()
204	            .filter(existing -> existing.getFirstName() != null
205	                && existing.getFirstName().equalsIgnoreCase(firstName)
206	                && existing.getLastName() != null
207	                && existing.getLastName().equalsIgnoreCase(lastName))
208	            .count();
209	    }
210	
211	    /**
212	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where
213	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} is the
214	     * upper-cased first three letters of the last name, and {@code NNNN} is a per-city 4-digit
215	     * zero-padded sequence equal to one more than the number of owners already in that city
216	     * (e.g. {@code 'SYD-SMI-0007'}).
217	     *
218	     * @param city     the owner's city
219	     * @param lastName the owner's last name
220	     * @return the assigned customer code
221	     */
222	    private String nextCustomerCode(String city, String lastName) {
223	        String cityPrefix = first3Upper(city);
224	        String lastPrefix = first3Upper(lastName);
225	        String cityKey = normalizeForHousehold(city);
226	        long sequence = this.clinicService.findAllOwners().stream()
227	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
228	            .count() + 1L;
229	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
230	    }
231	
232	    /**
233	     * Returns the upper-cased first three characters of {@code value}, or fewer if the value is
234	     * shorter. A {@code null} value yields the empty string.
235	     *
236	     * @param value the source value
237	     * @return the upper-cased first three characters
238	     */
239	    private String first3Upper(String value) {
240	        String v = (value == null ? "" : value);
241	        return v.substring(0, Math.min(3, v.length())).toUpperCase(java.util.Locale.ROOT);
242	    }
243	
244	    /**
245	     * Normalizes a street address applied whenever an owner is created: leading and trailing
246	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
247	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
248	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
249	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
250	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
251	     * {@code '12 MAIN STREET'}.
252	     *
253	     * @param address the raw address as submitted, or {@code null} when absent
254	     * @return the normalized address, or the empty string when the value is blank
255	     */
256	    private String normalizeAddress(String address) {
257	        String collapsed = (address == null ? "" : address)
258	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
259	        if (collapsed.isEmpty()) {
260	            return "";
261	        }
262	        String[] tokens = collapsed.split(" ");
263	        for (int i = 0; i < tokens.length; i++) {
264	            switch (tokens[i]) {
265	                case "ST" -> tokens[i] = "STREET";
266	                case "RD" -> tokens[i] = "ROAD";
267	                case "AVE" -> tokens[i] = "AVENUE";
268	                default -> { }
269	            }
270	        }
271	        return String.join(" ", tokens);
272	    }
273	
274	    /**
275	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
276	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
277	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
278	     * empty string.
279	     *
280	     * @param value the raw value (last name or address) as submitted
281	     * @return the normalized comparison key
282	     */
283	    private String normalizeForHousehold(String value) {
284	        if (value == null) {
285	            return "";
286	        }
287	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
288	    }
289	
290	    /**
291	     * Derives the stable shared household identifier for a household, keyed on the normalized last
292	     * name and address. Because it is a pure function of those normalized keys, every owner in the
293	     * same household deterministically computes the same value. The identifier is the first 12
294	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
295	     * (the separator prevents distinct name/address pairs from colliding).
296	     *
297	     * @param lastNameKey the normalized last-name comparison key
298	     * @param addressKey  the normalized address comparison key
299	     * @return the stable household identifier
300	     */
301	    private String householdId(String lastNameKey, String addressKey) {
302	        String seed = lastNameKey + "�" + addressKey;
303	        try {
304	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
305	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
306	            StringBuilder sb = new StringBuilder(digest.length * 2);
307	            for (byte b : digest) {
308	                sb.append(String.format("%02x", b));
309	            }
310	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
311	        }
312	        catch (java.security.NoSuchAlgorithmException e) {
313	            throw new IllegalStateException("SHA-256 not available", e);
314	        }
315	    }
316	
317	    /**
318	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
319	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
320	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
321	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
322	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
323	     * is stored as {@code '+61412345678'}.
324	     *
325	     * @param telephone the raw telephone number as submitted
326	     * @return the normalized E.164 telephone number
327	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
328	     *         number (8 to 15 digits after the '+')
329	     */
330	    private String normalizeTelephone(String telephone) {
331	        String raw = telephone == null ? "" : telephone.trim();
332	        String digits = raw.replaceAll("\\D", "");
333	        String e164;
334	        if (raw.startsWith("+")) {
335	            e164 = "+" + digits;
336	        } else {
337	            if (digits.startsWith("0")) {
338	                digits = digits.substring(1);
339	            }
340	            e164 = "+61" + digits;
341	        }
342	        int digitCount = e164.length() - 1;
343	        if (digitCount < 8 || digitCount > 15) {
344	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
345	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
346	        }
347	        return e164;
348	    }
349	
350	    /**
351	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
352	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
353	     * (absent) or already valid.
354	     *
355	     * @param email the email address as submitted, or {@code null} when absent
356	     * @return the lower-cased email, or {@code null} when absent
357	     */
358	    private String normalizeEmail(String email) {
359	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
360	    }
361	
362	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
363	    @Override
364	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
365	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
366	        if (currentOwner == null) {
367	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
368	        }
369	        currentOwner.setAddress(ownerFieldsDto.getAddress());
370	        currentOwner.setCity(ownerFieldsDto.getCity());
371	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
372	        currentOwner.setLastName(ownerFieldsDto.getLastName());
373	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
374	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
375	        this.clinicService.saveOwner(currentOwner);
376	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
377	    }
378	
379	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
380	    @Transactional
381	    @Override
382	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
383	        Owner owner = this.clinicService.findOwnerById(ownerId);
384	        if (owner == null) {
385	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
386	        }
387	        this.clinicService.deleteOwner(owner);
388	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
389	    }
390	
391	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
392	    @Override
393	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
394	        Owner owner = this.clinicService.findOwnerById(ownerId);
395	        if (owner == null) {
396	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
